const d = $json.body ?? $json;
const state = $getWorkflowStaticData('global');
state.lastDigestAt = new Date().toISOString();
state.lastAsof = d.asof;

const pct = (p) => `${Math.round(p * 100)}%`;
const cell = 'padding:6px 10px;border-bottom:1px solid #e2e8f0;';
const row = (r) => `<tr><td style="${cell}"><a href="${r.usaspending}">${r.piid}</a></td><td style="${cell}">${r.incumbent}</td><td style="${cell}">${r.agency}</td><td style="${cell}">${r.end_date}</td><td style="${cell}text-align:right">$${r.obligated_m}M</td><td style="${cell}text-align:right">${pct(r.p_change)}${r.delta !== undefined ? ` (${r.delta > 0 ? '+' : ''}${Math.round(r.delta * 100)} pts)` : ''}</td><td style="${cell}">${r.top_driver || ''}</td></tr>`;
const table = (title, rows) => rows && rows.length
  ? `<h3 style="color:#1e3a5f;margin:18px 0 6px">${title}</h3><table style="border-collapse:collapse;font-size:13px;color:#334155"><tr style="color:#0f172a;text-align:left"><th style="${cell}">Contract</th><th style="${cell}">Incumbent</th><th style="${cell}">Agency</th><th style="${cell}">Ends</th><th style="${cell}">Obligated</th><th style="${cell}">P(loses)</th><th style="${cell}">Top driver</th></tr>${rows.map(row).join('')}</table>`
  : '';

const html = `<div style="font-family:Arial,sans-serif;color:#334155;max-width:900px">
<p>Hey there Jason,</p>
<p>The FY27 recompete watchlist refreshed as of <b>${d.asof}</b>: ${d.contracts.toLocaleString()} contracts, $${d.obligated_b}B obligated, about ${d.expected_changes} expected to change hands.${d.added !== undefined ? ` ${d.added} added and ${d.dropped_off} dropped off since last week.` : ''}</p>
${table('New to the top 5%', d.new_to_top_band)}
${table('Top 5% ending within 90 days', d.top_band_ending_90d)}
${table('Biggest moves this week', d.biggest_moves)}
<p style="margin-top:18px"><a href="${d.app_url}" style="color:#0f766e">Open the watchlist app</a></p>
</div>`;

const n = (d.new_to_top_band || []).length;
return [{ json: { subject: `FY27 recompete watchlist: ${n} new in the top 5% (${d.asof})`, html } }];

const state = $getWorkflowStaticData('global');
const last = state.lastDigestAt ? new Date(state.lastDigestAt) : null;
const ageDays = last ? (Date.now() - last.getTime()) / 86400000 : Infinity;
if (ageDays <= 8) return [];
const when = last ? `${last.toISOString().slice(0, 10)} (${Math.floor(ageDays)} days ago)` : 'never';
const html = `<div style="font-family:Arial,sans-serif;color:#334155"><p>Hey there Jason,</p><p>No recompete watchlist digest has arrived since ${when}. The Monday GitHub Actions run may have failed or been disabled.</p><p><a href="https://github.com/jasonpellerin-aisolutionist/federal-recompete-cliff/actions/workflows/weekly-refresh.yml" style="color:#0f766e">Check the weekly refresh runs</a></p></div>`;
return [{ json: { subject: 'Recompete watchlist: weekly refresh missed', html } }];
